import type { Metadata } from "next";
import Page from "@/components/home-page/page";
import getAllTourCategories from "@/services/getTourCategories";
import { getBlogPosts } from "@/services/blog";
import { apiv2Base, apiv2ServerHeaders } from "@/services/apiv2";

// Hand-picked tours shown in the homepage "Featured & best-selling" carousel,
// in display order.
const FEATURED_TOUR_IDS: number[] = [
  5139, 2860, 9084, 8184, 157, 350, 6986, 8672,
];


// Keep your existing imports here

export const metadata: Metadata = {
  title: "TravelShop Booking: Adventure Travel & Holidays for Groups",
  description: "Explore flights, hotels, tours and travel experiences.",
};

async function getFeaturedTours() {
  if (!process.env.NEXT_PUBLIC_APIV3_URL) {
    return { tours: [], total: 0 };
  }

  const idsQuery = FEATURED_TOUR_IDS.map((id) => `ids[]=${id}`).join("&");

  try {
    // No `filters=` param → the endpoint returns the full tour object (routes,
    // startLocation, defaults, …) so the carousel renders the exact same card
    // as the category page instead of a stripped-down version.
    const res = await fetch(
      `${apiv2Base()}/b2c/tours/search?${idsQuery}&order_dir=desc&page_size=8&pax=2`,
      {
        next: { revalidate: 10800 },
        method: "GET",
        headers: {
          ...apiv2ServerHeaders(),
          "Content-type": "application/json",
          "Content-Language": "en",
          Accept: "*/*",
          "Accept-Encoding": "gzip, deflate, br",
          Origin: "https://travelshopbooking.com",
        },
      }
    );

    if (!res.ok) return { tours: [], total: 0 };

    // The endpoint ignores the id order, so re-sort to match FEATURED_TOUR_IDS.
    const data = await res.json();
    const tours = [...(data.tours ?? [])].sort(
      (a: any, b: any) =>
        FEATURED_TOUR_IDS.indexOf(a.id) - FEATURED_TOUR_IDS.indexOf(b.id)
    );
    return { ...data, tours };
  } catch {
    return { tours: [], total: 0 };
  }
}

async function getHomeBlogPosts() {
  try {
    return await getBlogPosts({ page: 1, limit: 4, sort: "newest" });
  } catch {
    return { data: [] };
  }
}

export default async function Home() {
  const fetchData = await getFeaturedTours();
  const tourCategories = await getAllTourCategories();
  const blogPosts = await getHomeBlogPosts();

  return (
    <Page
      featuredTours={fetchData}
      tourCategories={tourCategories}
      blogPosts={blogPosts?.data}
    />
  );
}
